import{_ as e,o as d,c as a,aj as o}from"./framework.js";const g=JSON.parse('{"title":"站点设置 | Cms / Settings | Documentation","description":"站点设置用于配置站点运行所需的基础信息、域名、第三方 服务集成、后台用户与权限、Hook 与 Cookie 等。与 运维中心 共用 /system 路径前缀，但 左侧菜单分组不同（本分组 menu.name 为 system，文案为「站点设置」）。","frontmatter":{"title":"站点设置 | Cms / Settings | Documentation","description":"站点设置用于配置站点运行所需的基础信息、域名、第三方 服务集成、后台用户与权限、Hook 与 Cookie 等。与 运维中心 共用 /system 路径前缀，但 左侧菜单分组不同（本分组 menu.name 为 system，文案为「站点设置」）。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/index.html"}]]},"headers":[],"relativePath":"zh/cms/settings/index.md","filePath":"cms/settings/index.md","lastUpdated":1780977342000}'),r={name:"zh/cms/settings/index.md"};function s(n,t,i,h,c,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="站点设置" tabindex="-1">站点设置 <a class="header-anchor" href="#站点设置" aria-label="Permalink to &quot;站点设置&quot;">​</a></h1><blockquote><p>菜单：左侧 <strong>站点设置</strong> 分组（须在 <strong>编辑菜单</strong> 中勾选显示） 路由前缀：<code>/_Admin/system/...?SiteId={站点GUID}</code></p></blockquote><p><strong>站点设置</strong>用于配置站点运行所需的基础信息、域名、第三方 <strong>服务集成</strong>、后台用户与权限、Hook 与 Cookie 等。与 <a href="./../operations/">运维中心</a> 共用 <code>/system</code> 路径前缀，但 <strong>左侧菜单分组不同</strong>（本分组 <code>menu.name</code> 为 <code>system</code>，文案为「站点设置」）。</p><div class="info custom-block"><p class="custom-block-title">高级菜单</p><p>整个 <strong>站点设置</strong> 分组在路由上标记为 <code>advanced: true</code>，默认不在左侧显示，须在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选。其中 <strong>角色权限</strong>、<strong>请求 Hook</strong>、<strong>操作 Hook</strong>、<strong>AI 服务</strong> 子项亦为 <code>advanced</code>。</p></div><div class="tip custom-block"><p class="custom-block-title">与运维中心的重叠</p><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td><strong>AI 服务</strong></td><td><code>/system/ai-service</code></td><td>与运维中心同名入口为 <strong>同一页面</strong>；文档只维护 <a href="./ai-service.html">AI 服务</a> 一份，两处互相链接</td></tr></tbody></table><p>运维侧其余菜单（访问日志、协作同步等）见 <a href="./../operations/">运维中心</a>。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>站点设置</strong> 及其需要的子项。</li><li>左侧展开 <strong>站点设置</strong>。</li></ol><h2 id="子菜单-与后台顺序一致" tabindex="-1">子菜单（与后台顺序一致） <a class="header-anchor" href="#子菜单-与后台顺序一致" aria-label="Permalink to &quot;子菜单（与后台顺序一致）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>菜单</th><th>路径</th><th>权限（feature）</th><th>文档</th><th>状态</th></tr></thead><tbody><tr><td>基础设置</td><td><code>/system/settings</code></td><td><code>site·edit</code></td><td><a href="./basic/">基础设置</a></td><td>✅</td></tr><tr><td>域名管理</td><td><code>/system/domains</code></td><td><code>domain</code></td><td><a href="./domains.html">域名管理</a></td><td>✅</td></tr><tr><td>服务集成</td><td><code>/system/config</code></td><td><code>config</code></td><td><a href="./integrations/">服务集成</a></td><td>✅</td></tr><tr><td>用户管理</td><td><code>/system/siteuser</code></td><td><code>siteUser</code></td><td><a href="./site-users.html">站点用户</a></td><td>✅</td></tr><tr><td>角色权限</td><td><code>/system/roles</code></td><td><code>role</code></td><td><a href="./roles.html">角色权限</a></td><td>✅</td></tr><tr><td>请求 Hook</td><td><code>/system/front-events</code></td><td><code>frontEvents</code></td><td><a href="./request-hooks.html">请求 Hook</a></td><td>✅</td></tr><tr><td>操作 Hook</td><td><code>/system/backend-events</code></td><td><code>backendEvents</code></td><td><a href="./action-hooks.html">操作 Hook</a></td><td>✅</td></tr><tr><td>Cookie 管理</td><td><code>/system/cookie</code></td><td><code>site·edit</code></td><td><a href="./cookie.html">Cookie</a></td><td>✅</td></tr><tr><td>AI 服务</td><td><code>/system/ai-service</code></td><td><code>ai</code></td><td><a href="./ai-service.html">AI 服务</a></td><td>✅</td></tr></tbody></table><p>深链示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/system/settings?SiteId={站点GUID}&amp;name=basic</span></span>\n<span class="line"><span>/_Admin/system/config?SiteId={站点GUID}&amp;group=Database</span></span>\n<span class="line"><span>/_Admin/system/front-events/edit?SiteId={站点GUID}&amp;name=RouteFinding&amp;display=RouteFinding</span></span>\n<span class="line"><span>/_Admin/system/backend-events/edit?SiteId={站点GUID}&amp;name=ContentUpdated&amp;display=ContentUpdated</span></span></code></pre></div><h2 id="无侧栏菜单的子路由" tabindex="-1">无侧栏菜单的子路由 <a class="header-anchor" href="#无侧栏菜单的子路由" aria-label="Permalink to &quot;无侧栏菜单的子路由&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路由</th><th>从哪进入</th><th>写入文档</th></tr></thead><tbody><tr><td><code>/system/settings?name={tab}</code></td><td>基础设置内 Tab 切换</td><td><a href="./basic/">基础设置</a> 各 Tab 子篇</td></tr><tr><td><code>/system/front-events/edit</code></td><td>请求 Hook 列表</td><td><a href="./request-hooks.html">请求 Hook</a></td></tr><tr><td><code>/system/backend-events/edit</code></td><td>操作 Hook 列表</td><td><a href="./action-hooks.html">操作 Hook</a></td></tr></tbody></table><h3 id="基础设置-tab-name-查询参数" tabindex="-1">基础设置 Tab（<code>name</code> 查询参数） <a class="header-anchor" href="#基础设置-tab-name-查询参数" aria-label="Permalink to &quot;基础设置 Tab（`name` 查询参数）&quot;">​</a></h3><table tabindex="0"><thead><tr><th><code>name</code></th><th>Tab 文案</th><th>主要内容</th></tr></thead><tbody><tr><td><code>basic</code></td><td>基础</td><td>显示名、Base URL、强制 SSL、SPA、<strong>多语言</strong>、导入/导出站点包</td></tr><tr><td><code>access</code></td><td>访问控制</td><td>IP / 地区限制等</td></tr><tr><td><code>performance</code></td><td>性能</td><td>缓存、压缩等站点性能项</td></tr><tr><td><code>seo</code></td><td>SEO</td><td>站点级 SEO 相关开关</td></tr><tr><td><code>editor</code></td><td>编辑器</td><td>后台编辑器偏好</td></tr><tr><td><code>advance</code></td><td>高级</td><td>默认数据库、SQL 日志、约束修复等（与 <a href="./../database/sql-logs.html">SQL 日志</a> 联动）</td></tr></tbody></table><p>多语言配置嵌在 <strong>基础</strong> Tab 的 <code>Multilingual</code> 区域，<strong>不单独成菜单</strong>；文档写在 <a href="./basic/general.html#多语言">基础 · 基础 Tab</a>，勿与 <a href="./../development/spa-multilingual.html">开发 → SPA 多语言</a> 混淆。</p><h2 id="服务集成-config-分组预览" tabindex="-1">服务集成（<code>config</code>）分组预览 <a class="header-anchor" href="#服务集成-config-分组预览" aria-label="Permalink to &quot;服务集成（`config`）分组预览&quot;">​</a></h2><p><strong>服务集成</strong>页按 <strong>Group</strong> 折叠展示 <code>CoreSetting</code> 项；详见 <a href="./integrations/">服务集成</a>。</p><table tabindex="0"><thead><tr><th>Group</th><th>文档</th></tr></thead><tbody><tr><td><strong>Database</strong></td><td><a href="./integrations/database.html">Database</a></td></tr><tr><td><strong>Payment</strong></td><td><a href="./integrations/payment.html">Payment</a></td></tr><tr><td><strong>SMS</strong></td><td><a href="./integrations/sms.html">SMS</a></td></tr><tr><td><strong>OAuth2</strong></td><td><a href="./integrations/oauth2.html">OAuth2</a></td></tr><tr><td><strong>Storage</strong></td><td><a href="./integrations/storage.html">Storage</a></td></tr><tr><td><strong>Others</strong></td><td><a href="./integrations/others.html">Others</a></td></tr></tbody></table><p>支付类集成 <strong>不在</strong> 电商设置里重复配置，以 <strong>Payment</strong> 分组为准。</p><h2 id="建议配置顺序" tabindex="-1">建议配置顺序 <a class="header-anchor" href="#建议配置顺序" aria-label="Permalink to &quot;建议配置顺序&quot;">​</a></h2><p>与实施常见路径一致，建议按下列顺序完成站点设置：</p><ol><li><strong><a href="./basic/">基础设置</a></strong> — 六 Tab 子篇（含多语言、SQL 日志开关等）</li><li><strong><a href="./domains.html">域名管理</a></strong> — 绑定、主域名、SSL</li><li><strong><a href="./integrations/">服务集成</a></strong> — 各 Group 子篇；Database / Payment 与 API 交叉链接</li><li><strong><a href="./site-users.html">站点用户</a></strong> · <strong><a href="./roles.html">角色权限</a></strong> — 后台账号与 feature 权限</li><li><strong><a href="./request-hooks.html">请求 Hook</a></strong> · <strong><a href="./action-hooks.html">操作 Hook</a></strong> — 含 edit 子页</li><li><strong><a href="./cookie.html">Cookie</a></strong></li><li><strong><a href="./ai-service.html">AI 服务</a></strong> — 与 <a href="./../operations/">运维中心</a> 互链</li></ol><h2 id="开发参考-kscript-api" tabindex="-1">开发参考（KScript / API） <a class="header-anchor" href="#开发参考-kscript-api" aria-label="Permalink to &quot;开发参考（KScript / API）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>后台能力</th><th>API 文档</th></tr></thead><tbody><tr><td>服务集成 CoreSetting</td><td><code>k.config</code> / 站点设置相关 API（按项补充）</td></tr><tr><td>支付</td><td><a href="/kb-docs/zh/api/payment/">k.payment</a></td></tr><tr><td>数据库连接</td><td><a href="/kb-docs/zh/api/database/">k.DB</a></td></tr><tr><td>多语言 / Label</td><td><a href="/kb-docs/zh/api/label/">k.label</a></td></tr><tr><td>JWT 等</td><td>集成项对应 API</td></tr></tbody></table><p>CMS 正文写 <strong>后台点击路径</strong> 与表单字段；脚本签名与示例留在 API 文档。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../navigation.html">站点后台菜单总览</a></td><td>全站菜单树</td></tr><tr><td><a href="./../database/">数据库</a></td><td>使用 Database 集成后的表管理</td></tr><tr><td><a href="./../operations/">运维中心</a></td><td>同前缀 <code>/system</code> 的观测与协作</td></tr></tbody></table>',28)])])}const b=e(r,[["render",s]]);export{g as __pageData,b as default};
